import { Controller, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

@Controller('api/v1')
export class FnSfr04005Controller {
  @Get('/departments')
  async listDepartments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const rawKeyword = query['keyword'];
    const keyword = typeof rawKeyword === 'string' ? rawKeyword.trim() : '';
    const rawPage = query['page'];
    const rawSize = query['size'];
    const page = rawPage === undefined || rawPage === '' ? 0 : Number(rawPage);
    const size = rawSize === undefined || rawSize === '' ? DEFAULT_SIZE : Number(rawSize);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'page는 0 이상의 정수여야 합니다.');
    }
    if (!Number.isInteger(size) || size < 1 || size > MAX_SIZE) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'size는 1 이상 200 이하의 정수여야 합니다.');
    }
    return transaction(async (db) => {
      const where = "WHERE (CAST(:keyword AS text) = '' OR name ILIKE '%' || CAST(:keyword AS text) || '%')";
      const rows = await db.query(
        'SELECT department_id AS "departmentId", parent_department_id AS "parentDepartmentId", name AS "name" FROM department ' +
          where +
          ' ORDER BY department_id LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)',
        { keyword, size, offset: page * size },
      );
      const counted = await db.query(
        'SELECT COUNT(*) AS "total" FROM department ' + where,
        { keyword },
      );
      const total = Number(counted[0]?.total ?? 0);
      return { items: rows, page, size, total };
    });
  }
}

