import { useState } from 'react';
import {
  Band,
  DataTable,
  Field,
  Filters,
  Num,
  Pager,
  RefName,
  TextInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;

export default function FnSfr04005Page({ role, notify }: PageProps) {
  const [deptInput, setDeptInput] = useState('');
  const [deptKeyword, setDeptKeyword] = useState('');
  const [deptPage, setDeptPage] = useState(0);
  const [empInput, setEmpInput] = useState('');
  const [empKeyword, setEmpKeyword] = useState('');

  const depts = useData<Page>(
    () => call<Page>('GET', '/departments', role, undefined, { keyword: deptKeyword, page: deptPage, size: SIZE }),
    [deptKeyword, deptPage],
  );

  const emps = useData<Page | undefined>(
    async () => {
      if (!empKeyword) return undefined;
      return call<Page>('GET', '/employees', role, undefined, { keyword: empKeyword });
    },
    [empKeyword],
  );

  const searchEmployees = () => {
    const text = empInput.trim();
    if (!text) {
      notify('검색어를 입력해 주세요.');
      return;
    }
    setEmpKeyword(text);
  };

  const pickDepartment = (row: Row) => {
    const name = String(row.name ?? '');
    setEmpInput(name);
    setEmpKeyword(name);
  };

  const empRows = emps.data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>부서 수</h2>
        <Num value={depts.data?.total ?? 0} />
      </section>
      <section className="box span-4">
        <h2>검색된 구성원</h2>
        <Num value={emps.data?.total ?? 0} />
      </section>
      <section className="box span-8">
        <h2>조직도</h2>
        <Filters
          onSearch={() => {
            setDeptPage(0);
            setDeptKeyword(deptInput.trim());
          }}
          onReset={() => {
            setDeptInput('');
            setDeptKeyword('');
            setDeptPage(0);
          }}
        >
          <Field label="검색어">
            <TextInput value={deptInput} onChange={setDeptInput} placeholder="부서명" />
          </Field>
        </Filters>
        <Band total={depts.data?.total} />
        {depts.error ? <p>{depts.error}</p> : null}
        <DataTable
          columns={[
            { key: 'name', label: '부서명' },
            {
              key: 'parentDepartmentId',
              label: '상위 부서',
              render: (row) =>
                row.parentDepartmentId ? (
                  <RefName table="department" role={role} value={row.parentDepartmentId} />
                ) : (
                  <span>최상위</span>
                ),
            },
          ]}
          rows={depts.data?.items ?? []}
          onRowClick={pickDepartment}
          empty="검색 결과가 없습니다."
        />
        <Pager page={deptPage} size={SIZE} total={depts.data?.total ?? 0} onPage={setDeptPage} />
      </section>
      <section className="box span-4">
        <h2>구성원</h2>
        <Filters
          onSearch={searchEmployees}
          onReset={() => {
            setEmpInput('');
            setEmpKeyword('');
          }}
        >
          <Field label="이름 또는 부서 검색어" required>
            <TextInput value={empInput} onChange={setEmpInput} placeholder="부서를 선택하거나 검색어 입력" />
          </Field>
        </Filters>
        {emps.error ? <p>{emps.error}</p> : null}
        <DataTable
          columns={[
            { key: 'name', label: '성명' },
            { key: 'departmentName', label: '부서명' },
          ]}
          rows={empRows}
          empty={empKeyword ? '검색 결과가 없습니다.' : '부서를 선택하거나 검색어를 입력해 주세요.'}
        />
      </section>
    </div>
  );
}
